# Untrapped Ultra Mode - UAUD diagnostic/self-repair interface
# UAUD ver 1.0.0 - TRUE BASELINE
$ErrorActionPreference='SilentlyContinue'
$UAUDName='UAUD';$UAUDVersion='1.0.0';$UAUDTitle="$UAUDName ver $UAUDVersion"
$Root=Split-Path -Parent $MyInvocation.MyCommand.Path;$Parent=Split-Path -Parent $Root;$ReportPath=Join-Path $Root 'diagnostic-latest.txt';$RepoBase='https://raw.githubusercontent.com/mehdishah5372-hue/Untrapped/main/';$StatusPath=$MyInvocation.MyCommand.Path;$SelfRepairPath=Join-Path $Root 'self-repair.ps1'
$ExtensionFiles=@('manifest.json','background.js','content.js','popup.html','popup.js','bootstrap.bundle.min.js')
$CoreFiles=@('INSTALL-PACKET-FILTER.ps1','INSTALL-ULTRA-MODE.ps1','config.json','create-override.ps1','generate-keys.ps1','packet-filter.ps1','self-repair.ps1','status-untrapped.ps1','test-untrapped.ps1','ultra-mode.ps1','verify-override.ps1')
$Lines=New-Object 'System.Collections.Generic.List[string]';$Problems=New-Object 'System.Collections.Generic.List[string]';$Status=New-Object 'System.Collections.Generic.List[string]';$RepairRan=$false;$UpdateState='UNKNOWN'
function Trace([string]$s){$x='['+(Get-Date -Format 'HH:mm:ss')+'] '+$s;Write-Host $x;[void]$Lines.Add($x)}
function Problem([string]$s){if($s -and -not($Problems -contains $s)){[void]$Problems.Add($s)}}
function StatusLine([string]$n,[string]$v,[string]$st=''){if($st){$x="$n`: $v [$st]"}else{$x="$n`: $v"};[void]$Status.Add($x);Write-Host ('[STATUS] '+$x)}
function Hash([byte[]]$b){$sha=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($sha.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
function Canonical([string]$p){try{$r=Invoke-WebRequest -Uri ($RepoBase+$p+'?cb='+[DateTime]::UtcNow.Ticks) -UseBasicParsing -TimeoutSec 30 -ErrorAction Stop;return [Text.Encoding]::UTF8.GetBytes([string]$r.Content)}catch{Trace ('[GITHUB] FAILED '+$p+': '+$_.Exception.Message);return $null}}
function Same([string]$remote,[string]$local){if(-not(Test-Path -LiteralPath $local)){return $false};$b=Canonical $remote;if($null -eq $b){return $null};try{return (Hash ([IO.File]::ReadAllBytes($local))) -eq (Hash $b)}catch{return $false}}
function Https([string]$h){try{return [bool](Test-NetConnection -ComputerName $h -Port 443 -WarningAction SilentlyContinue).TcpTestSucceeded}catch{return $false}}
function Find-BraveUntrapped{$out=@();$ud=Join-Path $env:LOCALAPPDATA 'BraveSoftware\Brave-Browser\User Data';if(Test-Path $ud){foreach($p in @(Get-ChildItem $ud -Directory -ErrorAction SilentlyContinue|Where-Object{$_.Name -eq 'Default' -or $_.Name -like 'Profile *'})){ $ed=Join-Path $p.FullName 'Extensions';foreach($v in @(Get-ChildItem $ed -Directory -Recurse -ErrorAction SilentlyContinue)){foreach($ver in @(Get-ChildItem $v.FullName -Directory -ErrorAction SilentlyContinue)){ $m=Join-Path $ver.FullName 'manifest.json';if(Test-Path $m){try{if(([string](Get-Content $m -Raw|ConvertFrom-Json).name)-eq 'Untrapped'){$out+=$ver.FullName}}catch{}}}}}};foreach($p in @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue|Where-Object{$_.Name -match '^brave' -and $_.CommandLine -match '(?i)--load-extension='})){foreach($m in [regex]::Matches($p.CommandLine,'--load-extension=([^\s"]+)')){$d=$m.Groups[1].Value;if(Test-Path (Join-Path $d 'manifest.json')){try{if(([string](Get-Content (Join-Path $d 'manifest.json') -Raw|ConvertFrom-Json).name)-eq 'Untrapped'){$out+=$d}}catch{}}}};return @($out|Sort-Object -Unique)}
function RunChecks{Trace '[POLICY] Reading config, schedule and override.';$scheduled=$false;$override=$false;try{$c=Get-Content (Join-Path $Root 'config.json') -Raw|ConvertFrom-Json;$s=[TimeSpan]::Parse([string]$c.start);$e=[TimeSpan]::Parse([string]$c.end);$n=(Get-Date).TimeOfDay;$in=if($s -eq $e){$true}elseif($s -lt $e){$n -ge $s -and $n -lt $e}else{$n -ge $s -or $n -lt $e};$o=Join-Path $Root 'override-until.txt';if(Test-Path $o){try{$u=[DateTime]::Parse((Get-Content $o -Raw)).ToUniversalTime();$override=[DateTime]::UtcNow -lt $u}catch{Problem 'Override file exists but is unreadable.'}};$scheduled=[bool]($c.enabled -and $in -and -not $override);StatusLine 'Policy' $(if($c.enabled){'ENABLED'}else{'DISABLED'});StatusLine 'Schedule' ($c.start+' - '+$c.end);StatusLine 'Scheduled blocking' $(if($scheduled){'ACTIVE'}else{'INACTIVE'});StatusLine 'Override' $(if($override){'ACTIVE'}else{'INACTIVE'})}catch{Problem 'Config is invalid or unreadable.';StatusLine 'Policy' 'UNREADABLE' 'FAIL'}
Trace '[POLICY] Testing actual target reachability.';$yt=Https 'www.youtube.com';$ch=Https 'chatgpt.com';$cr=Https 'www.crushon.ai';$expected=-not $scheduled;StatusLine 'YouTube' $(if($yt){'REACHABLE'}else{'BLOCKED'}) $(if($yt -eq $expected){'OK'}else{'MISMATCH'});StatusLine 'ChatGPT' $(if($ch){'REACHABLE'}else{'BLOCKED'}) $(if($ch -eq $expected){'OK'}else{'MISMATCH'});StatusLine 'CrushOn' $(if($cr){'REACHABLE'}else{'BLOCKED'}) $(if(-not $cr){'OK'}else{'MISMATCH'});if($yt -ne $expected){Problem 'YouTube does not match configured policy.'};if($ch -ne $expected){Problem 'ChatGPT does not match configured policy.'};if($cr){Problem 'CrushOn is reachable despite always-block policy.'}
Trace '[CORE] Checking repository core using correct ultra-mode/ canonical paths.';$coreBad=@();$coreUnknown=@();$missing=@();foreach($f in $CoreFiles){$lp=Join-Path $Root $f;$remote='ultra-mode/'+$f;if(-not(Test-Path $lp)){$missing+=$f;continue};$same=Same $remote $lp;if($same -eq $false){$coreBad+=$f}elseif($null -eq $same){$coreUnknown+=$f}};foreach($f in @('WinDivert.dll','WinDivert64.sys')){if(-not(Test-Path (Join-Path $Root $f))){$missing+=$f}};StatusLine 'Core source' $(if($coreBad.Count){$coreBad -join ', '}else{'CURRENT'}) $(if($coreBad.Count){'MISMATCH'}elseif($coreUnknown.Count){'UNVERIFIED'}else{'OK'});StatusLine 'Required files' $(if($missing.Count){$missing -join ', '}else{'PRESENT'}) $(if($missing.Count){'FAIL'}else{'OK'});if($coreBad.Count){Problem ('Untrapped core differs from canonical GitHub: '+($coreBad -join ', '))};if($missing.Count){Problem ('Required Untrapped files missing: '+($missing -join ', '))};$packet=@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue|Where-Object{$_.CommandLine -like '*packet-filter.ps1*'});$control=@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue|Where-Object{$_.CommandLine -like '*ultra-mode.ps1*'});StatusLine 'Packet filter' $(if($packet.Count){'RUNNING'}else{'STOPPED'}) $(if($packet.Count){'HEALTHY'}else{'FAIL'});StatusLine 'Control plane' $(if($control.Count){'RUNNING'}else{'STOPPED'}) $(if($control.Count){'HEALTHY'}else{'FAIL'});if(-not$packet.Count){Problem 'Packet filter is not running.'};if(-not$control.Count){Problem 'Control plane is not running.'}
Trace '[EXTENSION] Checking source.';$sourceBad=@();$sourceUnknown=@();foreach($f in $ExtensionFiles){$lp=Join-Path $Parent $f;if(-not(Test-Path $lp)){$sourceBad+=$f;continue};$same=Same $f $lp;if($same -eq $false){$sourceBad+=$f}elseif($null -eq $same){$sourceUnknown+=$f}};StatusLine 'Extension source' $(if($sourceBad.Count){$sourceBad -join ', '}else{'CURRENT'}) $(if($sourceBad.Count){'MISMATCH'}elseif($sourceUnknown.Count){'UNVERIFIED'}else{'OK'});if($sourceBad.Count){Problem ('Enhanced extension source differs from canonical GitHub: '+($sourceBad -join ', '))}
Trace '[BRAVE] Checking packaged and developer-loaded Brave extensions.';$installed=Find-BraveUntrapped;StatusLine 'Brave Untrapped copies' $installed.Count $(if($installed.Count){'FOUND'}else{'NOT FOUND'});if($installed.Count){foreach($d in $installed){$bad=@();foreach($f in $ExtensionFiles){$same=Same $f (Join-Path $d $f);if($same -eq $false){$bad+=$f}};StatusLine ('Brave copy '+$d) $(if($bad.Count){$bad -join ', '}else{'CURRENT'}) $(if($bad.Count){'MISMATCH'}else{'OK'});if($bad.Count){Problem ('Installed Brave Untrapped differs from canonical GitHub: '+($bad -join ', '))}}}else{Trace '[BRAVE] No installed packaged or --load-extension copy found; informational only.'}
Trace '[NETWORK] Checking DNS, HTTPS, Hosts, proxy, BFE and topology.';$ad=@(Get-NetAdapter|Where-Object{$_.Status -eq 'Up'});$rt=@(Get-NetRoute -DestinationPrefix '0.0.0.0/0');$dns=$false;try{$dns=@(Resolve-DnsName google.com -DnsOnly -ErrorAction Stop|Where-Object{$_.IPAddress}).Count -gt 0}catch{};$goo=Https 'www.google.com';$bfe=$false;try{$bfe=(Get-Service BFE).Status -eq 'Running'}catch{};$hp=Join-Path $env:SystemRoot 'System32\drivers\etc\hosts';$hh=@();if(Test-Path $hp){$hh=@(Get-Content $hp|Where-Object{$_ -match '(?i)(youtube|youtu\.be|chatgpt|crushon)' -and $_ -notmatch '^\s*#'})};$proxy='UNKNOWN';try{$z=netsh winhttp show proxy 2>$null;if($z -match 'Direct access'){$proxy='DIRECT'}elseif($z -match 'Proxy Server'){$proxy='CONFIGURED'}}catch{};$vpn=@(Get-NetAdapter|Where-Object{$_.Status -eq 'Up' -and $_.InterfaceDescription -match '(?i)vpn|wireguard|tun|tap|proton|speedify|warp|tailscale|openvpn'});StatusLine 'Active adapters' $ad.Count;StatusLine 'Default routes' $rt.Count;StatusLine 'VPN/tunnel adapters' $vpn.Count;StatusLine 'DNS google.com' $(if($dns){'OK'}else{'FAILED'}) $(if($dns){'HEALTHY'}else{'FAIL'});StatusLine 'Google HTTPS' $(if($goo){'OK'}else{'FAILED'}) $(if($goo){'HEALTHY'}else{'FAIL'});StatusLine 'Relevant Hosts' $(if($hh.Count){$hh.Count}else{'CLEAR'});StatusLine 'WinHTTP proxy' $proxy;StatusLine 'BFE' $(if($bfe){'RUNNING'}else{'NOT RUNNING/UNKNOWN'}) $(if($bfe){'HEALTHY'}else{'FAIL'});if(-not$dns){Problem 'External DNS resolution is failing.'};if(-not$goo){Problem 'External HTTPS connectivity to Google is failing.'};if($hh.Count){Problem 'Relevant Hosts entries were found.'};if(-not$bfe){Problem 'Base Filtering Engine is not running.'};return @{Problems=@($Problems);Scheduled=$scheduled;Override=$override;CoreBad=@($coreBad);CoreUnknown=@($coreUnknown);SourceBad=@($sourceBad);SourceUnknown=@($sourceUnknown);Installed=@($installed);Packet=$packet;Control=$control;Adapters=$ad;Routes=$rt;Vpn=$vpn;Dns=$dns;Google=$goo;Hosts=$hh;Proxy=$proxy;Bfe=$bfe}}
[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12;Trace "[START] === $UAUDTitle ===";Trace '[UPDATE] Checking diagnostic against canonical GitHub.'
try{$r=Canonical 'ultra-mode/status-untrapped.ps1';if($null -ne $r -and (Hash ([IO.File]::ReadAllBytes($StatusPath))) -ne (Hash $r)){$tmp=$StatusPath+'.update-'+[guid]::NewGuid().ToString('N')+'.tmp';[IO.File]::WriteAllBytes($tmp,$r);if((Hash ([IO.File]::ReadAllBytes($tmp))) -ne (Hash $r)){throw 'Update SHA-256 verification failed.'};Move-Item $tmp $StatusPath -Force;$UpdateState='UPDATED';Trace '[UPDATE] Updated successfully; current run continues.'}elseif($null -ne $r){$UpdateState='ALREADY CURRENT';Trace '[UPDATE] No update needed.'}else{$UpdateState='UNVERIFIED';Trace '[UPDATE] Canonical source unavailable; not a repair failure.'}}catch{$UpdateState='UNVERIFIED';Trace ('[UPDATE] '+$_.Exception.Message)}
$before=RunChecks;if($before.Problems.Count){Trace ('[AUTO-REPAIR] '+$before.Problems.Count+' issue(s); invoking UARD.');$RepairRan=$true;$p=Start-Process powershell.exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$SelfRepairPath) -WorkingDirectory $Root -Verb RunAs -WindowStyle Normal -PassThru -ErrorAction SilentlyContinue;if($p){$p.WaitForExit();Trace ('[AUTO-REPAIR] UARD exit code: '+$p.ExitCode)}else{Problem 'UARD could not be started.'};Trace '[VERIFY] Running full post-repair verification.';$after=RunChecks}else{$after=$before;Trace '[AUTO-REPAIR] No repair required.'}
$Problems=New-Object 'System.Collections.Generic.List[string]';foreach($p in $after.Problems){[void]$Problems.Add($p)};$overall=if($Problems.Count){'UNHEALTHY'}else{'HEALTHY'};$cond=@('CONDENSED DIAGNOSIS',' OVERALL: '+$overall,' Auto-update: '+$UpdateState,' Auto-repair triggered: '+$RepairRan,' Remaining problems: '+$Problems.Count);if($Problems.Count){foreach($p in $Problems){$cond+=' ! '+$p}}else{$cond+=' All checked components match canonical source and active policy.'};$cond+='';$cond+='DETAILED DIAGNOSIS';$cond+=' Core mismatches: '+$(if($after.CoreBad.Count){$after.CoreBad -join ', '}else{'NONE'});$cond+=' Core unverifiable: '+$(if($after.CoreUnknown.Count){$after.CoreUnknown -join ', '}else{'NONE'});$cond+=' Extension mismatches: '+$(if($after.SourceBad.Count){$after.SourceBad -join ', '}else{'NONE'});$cond+=' Brave copies found: '+$after.Installed.Count;$cond+=' Packet filter: '+$(if($after.Packet.Count){'RUNNING'}else{'STOPPED'});$cond+=' Control plane: '+$(if($after.Control.Count){'RUNNING'}else{'STOPPED'});$cond+=' DNS: '+$(if($after.Dns){'OK'}else{'FAILED'});$cond+=' Google HTTPS: '+$(if($after.Google){'OK'}else{'FAILED'});$cond+=' Hosts: '+$after.Hosts.Count;$cond+=' Proxy: '+$after.Proxy;$cond+=' BFE: '+$(if($after.Bfe){'RUNNING'}else{'NOT RUNNING/UNKNOWN'});$cond+='';$cond+='EXPLANATORY TABLE';$cond+='Component | Check | Automatic action';$cond+='Core | SHA-256 versus ultra-mode canonical files | UARD repairs';$cond+='Extension source | SHA-256 versus canonical extension | UARD repairs';$cond+='Brave extension | Packaged storage and --load-extension | UARD repairs detected copy';$cond+='Policy/reachability | Config, schedule, override and targets | Diagnose/trigger repair';$cond+='Network | DNS, HTTPS, Hosts, proxy, adapters, routes, VPN, BFE | Diagnose only';$cond+='';$cond+='VERSION / BASELINE';$cond+='Name: '+$UAUDName;$cond+='Version: '+$UAUDVersion;$cond+='TRUE BASELINE: 1.0.0';$cond+='';$cond+='DIAGNOSTIC CONTRACT';$cond+='Automatic changes are limited to Untrapped-owned components.';$cond+='Windows Firewall/WFP/DNS/routes/Hosts/proxy/adapters/VPN/override policy are never automatically modified.';$all=@($Lines)+@('')+$cond;$all|Set-Content $ReportPath -Encoding UTF8;Write-Host '';Write-Host "================ $UAUDTitle ================";$cond|ForEach-Object{Write-Host $_};Write-Host '';foreach($s in $Status){Write-Host $s};Write-Host '';Write-Host ('Report: '+$ReportPath)